SELECT CASE WHEN c.age >= 55 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END AS age_bucket, ROUND((100 * SUM(CASE WHEN t.merchant = 'Lazada' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lazada, SUM(CASE WHEN t.merchant = '7-Eleven' THEN 1 ELSE 0 END) AS 7_eleven_count FROM transactions t JOIN accounts a ON t.account_id = a.id JOIN customers c ON a.customer_id = c.id GROUP BY CASE WHEN c.age >= 55 THEN 'high' WHEN c.age >= 38 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN t.merchant = '7-Eleven' THEN 1 ELSE 0 END) > 21 ORDER BY pct_lazada DESC, age_bucket LIMIT 10;
